/* Panel de contenido de MSG-01. Todo el color sale de un token `var(--bw-*)`:
   este fichero no escribe ni un hex ni un rgb(). */

.screen {
  background: var(--bw-cold-white);
  font-family: var(--bw-font-body);
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0 0 16px;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* ── Barra de acciones ─────────────────────────────────────────────────── */

.actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
  pointer-events: none;
}

.search {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-surface-mist);
  color: var(--bw-input-text);
  font-family: var(--bw-font-body);
  font-size: 13px;
  outline: none;
  transition: border-color 0.15s ease;
}

.search:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.search::placeholder {
  color: var(--bw-input-placeholder);
}

.primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

/* `Nuevo contacto` no lleva a ningún sitio: se apaga y se queda apagado. */
.primary:disabled {
  background: var(--bw-line-steel);
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.scope {
  font-size: 12px;
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

.count {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

/* ── Avisos ────────────────────────────────────────────────────────────── */

.error {
  margin-bottom: 14px;
  padding: 10px 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: 13px;
  line-height: 1.5;
}

.status {
  margin: 0 0 14px;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

/* ── Paginación ────────────────────────────────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.page,
.pageCtrl {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-surface-mist);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: 12px;
  cursor: pointer;
  transition: border-color 0.12s ease, color 0.12s ease;
}

.page:hover,
.pageCtrl:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

.pageCtrl:disabled {
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

