import { useEffect, useState, type FormEvent, type KeyboardEvent } from 'react';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — el panel de contenido, no un componente de
 * presentación.
 *
 * Es la pantalla la que habla con la capa de datos (`fetchThreadPage` con
 * `profile.orgId`) y la que posee el estado de búsqueda y de página. `ThreadList`
 * solo pinta lo que recibe.
 *
 * El aviso E2EE del HTML aprobado con su botón «Introducir frase de seguridad» NO
 * se reproduce: en el MVP las claves viven en memoria de sesión y no hay
 * passphrase, ni backup, ni recuperación (CLAUDE.md §4; Plan §9 «Fuera»). Pintar
 * ese botón como acción disponible sería el riesgo #1 del proyecto en la
 * interfaz, donde además engaña porque parece verificable. Tampoco se pinta el
 * «punto azul + recuento» de no leídos: el esquema no tiene ningún seguimiento de
 * lectura, así que el número no tiene de dónde salir (F-027).
 */

interface MessagesProps {
  profile: MemberProfile;
  /**
   * Inyectable para que los tests no dependan del reloj; por defecto,
   * `new Date()`. El tipo es `Date | undefined` y NO solo `Date` (F-137): bajo
   * `exactOptionalPropertyTypes` un `undefined` que llegue aquí tiene que poder
   * pasarse hacia abajo sin un `TS2375` que no protegía nada.
   */
  now?: Date | undefined;
  /**
   * La firma pública del componente (F-118). El shell la pasa desde `App.tsx`,
   * que se cableó DESPUÉS de escribirse esta tarea; MSG-02 no existía entonces y
   * abrir un hilo no lleva a ningún sitio. Se declara para que el repo compile y
   * se IGNORA: nada de lo que hay en `out_of_scope` cambia por esto.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * El texto del fallo, con el fallo dentro (F-128, que es F-020 literal).
 *
 * Lo que se captura NO es siempre un `Error`: PostgREST rechaza con un objeto
 * plano `{ code, message }`, así que `String(e)` da `[object Object]` y
 * `e.message` da `undefined`. Un aviso que dice «No se pudieron cargar los hilos»
 * y se come el código deja al socio sin la única pista que explicaba el fallo.
 */
function describeError(e: unknown): string {
  if (e instanceof Error) return e.message;
  if (typeof e === 'object' && e !== null) {
    const code = (e as { code?: unknown }).code;
    const message = (e as { message?: unknown }).message;
    const parts: string[] = [];
    if (typeof code === 'string' && code !== '') parts.push(code);
    if (typeof message === 'string' && message !== '') parts.push(message);
    if (parts.length > 0) return parts.join(' · ');
  }
  return String(e);
}

/**
 * MSG-02 no existe todavía: abrir un hilo no lleva a ningún sitio. Se pasa un
 * no-op a `ThreadList` en vez de cablear `onOpenThread`, que llega del shell y se
 * ignora a propósito (F-118).
 */
function ignoreOpen(): void {
  /* sin destino en el MVP */
}

export function Messages(props: MessagesProps) {
  const { profile, now = new Date() } = props;

  /** Lo que hay escrito en el input ahora mismo. */
  const [search, setSearch] = useState('');
  /** Lo que se envió de verdad, al pulsar Enter. Es lo que va a la consulta. */
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((res) => {
        if (!alive) return;
        setThreads(res.threads);
        setTotal(res.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (!alive) return;
        setThreads([]);
        setTotal(0);
        setError(describeError(e));
        setLoading(false);
      });

    return () => {
      alive = false;
    };
  }, [profile.orgId, query, page]);

  const totalPages = pageCount(total);

  function applySearch(): void {
    setQuery(search.trim());
    setPage(1);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    applySearch();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>): void {
    if (event.key === 'Enter') {
      event.preventDefault();
      applySearch();
    }
  }

  const pages: number[] = [];
  for (let p = 1; p <= totalPages; p += 1) pages.push(p);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.actions}>
        <form className={styles.searchWrap} role="search" onSubmit={handleSubmit}>
          <i className={styles.searchIcon} aria-hidden="true" />
          <input
            type="text"
            className={styles.search}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            onKeyDown={handleKeyDown}
          />
        </form>

        {/* DIR-01 no está entre las 8 pantallas del alcance (Plan §9): el control
            existe, pero no lleva a ninguna parte y no se pinta como si lo
            hiciera. El motivo visible va en su propio nodo. */}
        <button type="button" className={styles.primary} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span data-testid="directorio-scope" className={styles.scope}>
          El Directorio está fuera del MVP.
        </span>

        <span data-testid="pag-info" className={styles.count}>
          {`${total} hilos · Página ${page} de ${totalPages}`}
        </span>
      </div>

      {/* `role="alert"` no sale gratis del HTML (F-127): hay que escribirlo, y
          solo aquí. La carga y el vacío no interrumpen, así que no lo llevan. */}
      {error !== null && (
        <div className={styles.error} role="alert">
          {`No se pudieron cargar los hilos. ${error}`}
        </div>
      )}

      {error === null && loading && <p className={styles.status}>Cargando hilos...</p>}

      {error === null && !loading && (
        <ThreadList threads={threads} now={now} onOpen={ignoreOpen} />
      )}

      {error === null && !loading && total > 0 && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={styles.pageCtrl}
            aria-label="Página anterior"
            disabled={page <= 1}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            <i className="ti ti-chevron-left" aria-hidden="true" />
          </button>

          {/* Los botones de página se encuentran por su NÚMERO y por eso NO
              llevan `aria-label`: el nombre accesible lo decide el `aria-label`
              en cuanto existe, y «Página 2» deja de encontrarse buscando «2»
              (F-145). El número va como texto. */}
          {pages.map((p) => (
            <button
              key={p}
              type="button"
              className={p === page ? `${styles.page} ${styles.pageActive}` : styles.page}
              onClick={() => setPage(p)}
            >
              {p}
            </button>
          ))}

          <button
            type="button"
            className={styles.pageCtrl}
            aria-label="Página siguiente"
            disabled={page >= totalPages}
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
          >
            <i className="ti ti-chevron-right" aria-hidden="true" />
          </button>
        </div>
      )}
    </div>
  );
}

