/* Lista de hilos de MSG-01. Todo el color sale de un token `var(--bw-*)`:
   este fichero no escribe ni un hex ni un rgb(). */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

/* La fila pulsable es este botón, no el `<li>`: el `<li>` conserva su rol
   `listitem` y el nombre accesible del hilo vive aquí dentro (F-131). */
.rowBtn {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas:
    'top time'
    'preview state';
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  text-align: left;
  font-family: var(--bw-font-body);
  cursor: pointer;
  transition: background 0.1s ease;
}

.rowBtn:hover {
  background: var(--bw-hover-surface);
}

.rowBtn:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.top {
  grid-area: top;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.country {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  padding: 1px 6px;
  border-radius: var(--bw-radius);
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.time {
  grid-area: time;
  justify-self: end;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.preview {
  grid-area: preview;
  font-size: 12px;
  color: var(--bw-steel-mist);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  grid-area: state;
  justify-self: end;
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: var(--bw-radius);
  white-space: nowrap;
}

/* Los cinco tonos de `stateTone`, resueltos contra los tokens de §1.5. El hex lo
   da la spec; el token, el sistema de diseño. */

/* ABIERTO — Steel Mist. */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

/* CON CONSULTA PENDIENTE — azul de calibración. */
.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border-color: var(--bw-chip-active-border);
}

/* CON OFERTA PENDIENTE — ámbar. */
.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

/* ACUERDO ALCANZADO — verde. */
.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border-color: var(--bw-badge-success-border);
}

/* CERRADO SIN ACUERDO — Steel Mist apagado y tachado. */
.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border-color: var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío ─────────────────────────────────────────────────────────
   Contenedor propio, nunca un `<li>`: con la lista vacía no puede quedar
   ningún `listitem` en el documento (F-141). */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 40px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
}

.emptyText {
  margin: 0;
  max-width: 460px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-deep-steel);
}

.emptyBtn {
  height: 36px;
  padding: 0 18px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-cold-white);
  color: var(--bw-input-placeholder);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
}

.emptyReason {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

