import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, escrita a mano.
 *
 * Presentacional y nada más: pinta las filas **en el orden que las recibe** (el
 * orden por `last_item_at` descendente lo pone el servidor, en `fetchThreadPage`)
 * y al abrir un hilo avisa con el **ID**, nunca con el objeto.
 *
 * Dos cosas de forma que no se ven y son las que rompen a mano:
 *
 * 1. `TONE_CLASS` es `Record<StateTone, string | undefined>` y no
 *    `Record<StateTone, string>` (F-143). Con `noUncheckedIndexedAccess` activo,
 *    cualquier propiedad de un CSS Module se tipa `string | undefined` porque el
 *    fichero `.css` no es un tipo cerrado para TypeScript; el `?? ''` va en el
 *    único punto donde se consume la clase, para que una que falte deje la fila
 *    sin adorno en vez de escribir la palabra «undefined» en el atributo.
 *
 * 2. La fila es un `<li>` que SIGUE siendo `listitem`, con un `<button>` DENTRO
 *    (F-131). Un `role="button"` sobre el propio `<li>` no se suma al implícito:
 *    lo sustituye, y entonces desaparecen los `listitem` y aparecen dos botones
 *    con el mismo nombre accesible.
 */

/** Tono → clase del badge. Ver arriba por qué el valor es `string | undefined`. */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

/**
 * El texto del estado vacío, entero y verbatim (F-147).
 *
 * Va en una constante y en un solo nodo de texto porque el contrato lo busca con
 * `getByText(<cadena>)`, que compara el texto de UN elemento: partirlo en título
 * y cuerpo deja el aserto sin nada que encontrar.
 */
const EMPTY_TEXT =
  'Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.';

/** El motivo visible de que el botón esté apagado. Lleva el literal, verbatim. */
const EMPTY_REASON = 'El Directorio está fuera del MVP.';

interface ThreadListProps {
  threads: ThreadSummary[];
  /**
   * Inyectable para que los tests no dependan del reloj. El tipo es
   * `Date | undefined`, no `Date` (F-137): bajo `exactOptionalPropertyTypes` un
   * `undefined` que llegue desde `Messages` tiene que poder pasarse, y
   * `relativeTime` ya trae su propio `new Date()` de respaldo.
   */
  now?: Date | undefined;
  /** Avisa con el ID del hilo. El destino (MSG-02) no está en el MVP. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  // El estado vacío NO va colgado de una lista vacía ni dentro de un `<ul>`
  // (F-141): con `threads` vacío no puede quedar ningún `listitem` en el
  // documento, así que el contenedor es un `<div>` hermano y fuera de la lista.
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>{EMPTY_TEXT}</p>
        {/* Un botón que parece pulsable y no lleva a ningún sitio es la regla de
            CLAUDE.md §7 en la interfaz: se pinta deshabilitado y con el motivo
            al lado, igual que el botón de subida de INV-01 (F-023 e). */}
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyReason}>{EMPTY_REASON}</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          <button
            type="button"
            className={styles.rowBtn}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.top}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              <span className={styles.country}>{thread.counterpartyCountry}</span>
            </span>
            <span className={styles.time}>{relativeTime(thread.lastItemAt, now)}</span>
            <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
            {/* El estado del hilo es literal del CHECK de la migración 0003: no
                se traduce ni se abrevia. */}
            <span className={`${styles.badge} ${TONE_CLASS[stateTone(thread.state)] ?? ''}`}>
              {thread.state}
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
